            : t("winnerNotice", {
                winner:
                  p.winner === "Black" ? t("colorBlack") : t("colorWhite"),
              })
          : l.phase === "countdown"
            ? t("startingSoon")
            : l.phase === "lobby"
              ? t("waitingForPlayers")
              : t("turnToMove", {
                  color:
                    p.turn === "Black" ? t("colorBlack") : t("colorWhite"),
