  return (
    <main className="gd-product">
      <div className="gd-content">
        <header className="gd-gamebar">
          <div className="gd-game-title">
            <strong aria-live="polite">{title}</strong>
            <small>
              {t("roundDetail", {
                round: l.round || 1,
