            {(!l.round || p.winner || run?.status === "paused") && (
              <button
                className="gd-button gd-main-action"
                id="start"
                disabled={busy || !candidates}
                onClick={openRound}
              >
                <Play size={14} />
                {!l.round
                  ? t("play")
                  : run?.status === "paused"
                    ? t("newGame")
                    : t("rematch")}
              </button>
            )}
          </div>
        </header>
        {error && (
          <div className="gd-alert" role="alert">
            <span>{errorText(error.cause)}</span>
            {error.retry && (
              <button
                className="gd-button"
                disabled={busy}
                onClick={() =>
                  void perform(
                    error.retry === "candidates"
                      ? () => loadCandidates()
