      topic === "invitation"
        ? t("notifyInviteSummary")
        : topic === "result"
          ? p.winner === "draw"
            ? t("notifyMatchDrawn")
            : t("notifyMatchFinished", { name: name || "" })
          : t("notifyWaitingMoveSummary", { color });
