  role: string | undefined,
  context: InteractionContext,
) =>
  change(async () => {
    const who = actor(context),
      old = lobby();
    const next =
      action === "join"
        ? joinSeat(old, role!, who.id)
        : action === "leave"
          ? leaveSeat(old, who.id)
