// only the interface response that is returned to the calling model.
function defineGameInterface<T>(definition: Parameters<typeof pudding.defineInterface<T>>[0]) {
  return pudding.defineInterface({
    ...definition,
    async run(input, context) {
      try {
        return await definition.run(input, context);
      } catch (error) {
        throw new Error(errorText(error));
      }
    },
  });
}
function registerInterfaces() {
  const coordinates = { error: errorText("Use columns A–O and rows 1–15") };
  return [
    defineGameInterface({
      name: "joinSeat",
      description: t("descJoinSeat"),
      input: z.object({ role: z.enum(roles) }).strict(),
      run: (i, c) => changeSeat("join", i.role, c),
    }),
    defineGameInterface({
      name: "ready",
      description: t("descReady"),
      input: z.object({ ready: z.boolean().optional() }).strict(),
      run: (i, c) =>
        changeSeat(i.ready === false ? "unready" : "ready", undefined, c),
    }),
    defineGameInterface({
      name: "leaveSeat",
      description: t("descLeaveSeat"),
      input: z.object({}).strict(),
      run: (_, c) => changeSeat("leave", undefined, c),
    }),
    defineGameInterface({
      name: "placeStone",
      description: t("descPlaceStone"),
      input: z
        .object({
          row: z
            .number(coordinates)
            .int(coordinates)
            .min(1, coordinates)
            .max(15, coordinates),
          column: z
            .string(coordinates)
            .regex(/^[A-O]$/, coordinates),
          comment: z
            .string()
            .trim()
            .max(40, errorText("Keep your comment within 40 characters"))
            .optional(),
        })
        .strict(),
      run: move,
    }),
    defineGameInterface({
      name: "readBoard",
      description: t("descReadBoard"),
      input: z.object({ includeHistory: z.boolean().optional() }).strict(),
      run: (i, c) => readBoard(c, i.includeHistory),
    }),
    defineGameInterface({
      name: "resign",
      description: t("descResign"),
      input: z.object({}).strict(),
      run: (_, c) => resign(c),
    }),
  ];
}
let interfaces = registerInterfaces();
pudding.locale.subscribe(() => {
  interfaces.forEach((remove) => remove());
  interfaces = registerInterfaces();
});
pudding.interaction.onResume(async () => {
  if (changing || !lobby().round || position().winner) return;
  await change(async () => {
    const l = lobby();
    // Restored countdowns start from three again; an in-game clock keeps only
    // active thinking time that was committed before the explicit pause.
    await save(
      l.phase === "countdown" ? { ...l, startsAt: Date.now() + 3000 } : l,
      l.phase === "playing" ? resumeClock(position()) : position(),
    );
    await publish(true);
  });
});

